//! Build the port's C++ runtime (libc++ + libc++abi) for one minix target.
//!
//! Writes `target/cxx/<arch>/minix-runtime/libstdc++.a`, the one archive
//! [`crate::cc::dso`] links into Mesa's shared objects. The flags that differ per
//! target (the red zone, RISC-V's `-march`/`-mabi`) come from [`Arch`], so they
//! agree with the C compiles `crate::cc::dso` does for the same arch.
//!
//! libc++ builds against `target/cxx/toolchain-<machine>.cmake`, generated by
//! [`toolchain`]. libc++abi is built with explicit flags, because its cmake never
//! reads the toolchain's `C_FLAGS_INIT`.

use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::process::Command;

use crate::arch::{self, Arch};
use crate::cc;
use crate::toolchain;

fn libcxx_src(root: &Path) -> PathBuf {
    root.join("rust").join("src").join("llvm-project").join("libcxx")
}

fn libcxxabi_src(root: &Path) -> PathBuf {
    root.join("rust").join("src").join("llvm-project").join("libcxxabi")
}

fn cxx_root(root: &Path, arch: &Arch) -> PathBuf {
    root.join("target").join("cxx").join(arch.name)
}

/// The freestanding PIC flags a C/C++ object for this target needs.
fn host_flags(arch: &Arch) -> Vec<String> {
    let mut flags = arch.pic_cflags();
    flags.push("-fno-stack-protector".to_string());
    flags
}

/// A literal backslash-quote, which cmake needs around a path inside a quoted
/// value (`clang -print-resource-dir` can be `/Program Files/...`, spaces and
/// all).
fn quoted(text: &str) -> String {
    format!("\\\"{text}\\\"")
}

/// The `C_FLAGS` value the toolchain file carries.
///
/// `-fPIC`, not the executable `-fno-pic` [`Arch::base_cflags`] carries: the
/// runtime is linked into shared objects.
fn toolchain_c_flags(arch: &Arch) -> String {
    let mut flags = arch.pic_cflags();
    flags.push("-fno-stack-protector".to_string());
    flags.push("-O2".to_string());
    flags.push("-nostdinc".to_string());
    flags.push(format!("-isystem {}", quoted("${MINIX_CLANG_INC}")));
    flags.push(format!("-I{}", quoted("${MINIX_ROOT}/tools/c-include")));
    flags.join(" ")
}

fn toolchain_cxx_flags(arch: &Arch) -> String {
    format!(
        "{} -nostdinc++ -isystem {} -isystem {}",
        toolchain_c_flags(arch),
        quoted("${MINIX_ROOT}/rust/src/llvm-project/libcxx/include"),
        quoted("${MINIX_ROOT}/rust/src/llvm-project/libcxxabi/include"),
    )
}

/// The text of `target/cxx/toolchain-<machine>.cmake`.
///
/// It lives under `target/` because it embeds the absolute repo path, which is
/// machine-specific; this function is the tracked half that regenerates it.
pub fn toolchain_text(root: &Path, arch: &Arch) -> String {
    let root = root.to_string_lossy().replace('\\', "/");
    let c = toolchain_c_flags(arch);
    let cxx = toolchain_cxx_flags(arch);
    format!(
        "\
# Generated by `cargo xtask build libcxx-toolchain`. Do not edit.
set(CMAKE_SYSTEM_NAME Generic)
set(CMAKE_SYSTEM_PROCESSOR {machine})
set(CMAKE_TRY_COMPILE_TARGET_TYPE STATIC_LIBRARY)

set(MINIX_ROOT \"{root}\")
set(MINIX_TRIPLE {triple})

find_program(MINIX_CLANG clang REQUIRED)
find_program(MINIX_CLANGXX clang++ REQUIRED)
find_program(MINIX_AR llvm-ar REQUIRED)
find_program(MINIX_RANLIB llvm-ranlib REQUIRED)

set(CMAKE_C_COMPILER \"${{MINIX_CLANG}}\")
set(CMAKE_CXX_COMPILER \"${{MINIX_CLANGXX}}\")
set(CMAKE_AR \"${{MINIX_AR}}\")
set(CMAKE_RANLIB \"${{MINIX_RANLIB}}\")
set(CMAKE_C_COMPILER_TARGET \"${{MINIX_TRIPLE}}\")
set(CMAKE_CXX_COMPILER_TARGET \"${{MINIX_TRIPLE}}\")

execute_process(COMMAND \"${{MINIX_CLANG}}\" -print-resource-dir
                OUTPUT_VARIABLE MINIX_CLANG_RES
                OUTPUT_STRIP_TRAILING_WHITESPACE)
set(MINIX_CLANG_INC \"${{MINIX_CLANG_RES}}/include\")

set(MINIX_C_FLAGS \"{c}\")
# Order matters: libc++ first, then the C headers, then the generated config dir
# the build adds itself (libc++'s <string.h> guard skips the C headers otherwise).
set(MINIX_CXX_FLAGS \"{cxx}\")

set(CMAKE_C_FLAGS_INIT \"${{MINIX_C_FLAGS}}\")
set(CMAKE_CXX_FLAGS_INIT \"${{MINIX_CXX_FLAGS}}\")
",
        machine = arch.machine,
        triple = arch.clang_target(),
    )
}

/// Write the toolchain file for one arch.
pub fn write_toolchain(root: &Path, arch: &Arch) -> io::Result<()> {
    let out = root
        .join("target")
        .join("cxx")
        .join(format!("toolchain-{}.cmake", arch.machine));
    if let Some(parent) = out.parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(&out, toolchain_text(root, arch))?;
    println!("wrote {}", out.display());
    Ok(())
}

pub fn toolchain_command(root: &Path, target: Option<&str>) -> io::Result<()> {
    write_toolchain(root, resolve(target)?)
}

pub fn run(root: &Path, target: Option<&str>) -> io::Result<()> {
    let arch = resolve(target)?;
    let cmake = need("cmake")?;
    let ninja = need("ninja")?;
    let llvm_ar = need("llvm-ar")?;
    write_toolchain(root, arch)?;

    let toolchain_file = root
        .join("target")
        .join("cxx")
        .join(format!("toolchain-{}.cmake", arch.machine));
    let base = cxx_root(root, arch);
    let libcxx_build = base.join("libcxx-build");
    let libcxxabi_build = base.join("libcxxabi-build");
    let libcxx = libcxx_src(root);
    let libcxxabi = libcxxabi_src(root);

    // The IWYU mapping step needs a Python that can import libcxx's local modules.
    // The host's is fine where it is a real CPython; on Windows the only python is
    // the embeddable one beside LLVM, whose `._pth` pins sys.path, so a stub .cmd
    // does the (unused) step instead.
    let python = if cfg!(windows) {
        root.join("tools").join("libcxx-iwyu.cmd").to_string_lossy().to_string()
    } else {
        "python3".to_string()
    };

    for directory in [&libcxx_build, &libcxxabi_build] {
        remove_dir_all(directory)?;
    }

    let root_posix = root.to_string_lossy().replace('\\', "/");
    let libcxx_flags = format!(
        "-I{root_posix}/rust/src/llvm-project/libcxxabi/include;-D_POSIX_TIMERS=200809L"
    );

    let mut configure = Command::new(&cmake);
    configure
        .args(["-G", "Ninja", "-S"])
        .arg(&libcxx)
        .arg("-B")
        .arg(&libcxx_build)
        .arg(format!("-DCMAKE_TOOLCHAIN_FILE={}", toolchain_file.display()))
        .args(["-DCMAKE_BUILD_TYPE=Release", "-DLIBCXX_ENABLE_SHARED=OFF"])
        .args(["-DLIBCXX_ENABLE_STATIC=ON", "-DLIBCXX_ENABLE_EXCEPTIONS=OFF"])
        .args(["-DLIBCXX_ENABLE_RTTI=OFF", "-DLIBCXX_ENABLE_FILESYSTEM=OFF"])
        .args(["-DLIBCXX_ENABLE_LOCALIZATION=OFF", "-DLIBCXX_ENABLE_MONOTONIC_CLOCK=ON"])
        .args(["-DLIBCXX_ENABLE_NEW_DELETE_DEFINITIONS=OFF", "-DLIBCXX_ENABLE_RANDOM_DEVICE=ON"])
        .args(["-DLIBCXX_ENABLE_ABI_LINKER_SCRIPT=OFF", "-DLIBCXX_ENABLE_THREADS=ON"])
        .args(["-DLIBCXX_HAS_PTHREAD_API=ON", "-DLIBCXX_ABI_VERSION=1"])
        .args(["-DLIBCXX_ABI_NAMESPACE=__1", "-DLIBCXX_CXX_ABI=system-libcxxabi"])
        .arg(format!(
            "-DLIBCXX_CXX_ABI_INCLUDE_PATHS={}",
            libcxxabi.join("include").display()
        ))
        .args(["-DLIBCXX_AVAILABILITY_MINIMUM_HEADER_VERSION=2"])
        .args(["-DLIBCXX_SHARED_OUTPUT_NAME=cxx-shared", "-DLIBCXX_INCLUDE_TESTS=OFF"])
        .arg(format!("-DLIBCXX_ADDITIONAL_COMPILE_FLAGS={libcxx_flags}"))
        .arg(format!("-DPython3_EXECUTABLE={python}"));
    step(&mut configure, "configuring libc++")?;

    let mut build = Command::new(&ninja);
    build.args(["-C"]).arg(&libcxx_build);
    step(&mut build, "building libc++")?;

    let cflags = format!(
        "{} -O2 -I{root_posix}/tools/c-include",
        host_flags(arch).join(" ")
    );
    let cxxflags = format!(
        "{} -O2 -std=c++23 -nostdinc++ -I{root_posix}/rust/src/llvm-project/libcxx/include -I{root_posix}/tools/c-include -I{root_posix}/target/cxx/{}/libcxx-build/include/c++/v1",
        host_flags(arch).join(" "),
        arch.name
    );

    let mut configure_abi = Command::new(&cmake);
    configure_abi
        .args(["-G", "Ninja", "-S"])
        .arg(&libcxxabi)
        .arg("-B")
        .arg(&libcxxabi_build)
        .arg(format!("-DCMAKE_TOOLCHAIN_FILE={}", toolchain_file.display()))
        .args(["-DCMAKE_BUILD_TYPE=Release"])
        .arg(format!("-DCMAKE_C_FLAGS={cflags}"))
        .arg(format!("-DCMAKE_CXX_FLAGS={cxxflags}"))
        .args(["-DLIBCXXABI_ENABLE_SHARED=OFF", "-DLIBCXXABI_ENABLE_STATIC=ON"])
        .args(["-DLIBCXXABI_BAREMETAL=ON", "-DLIBCXXABI_ENABLE_THREADS=OFF"])
        .args(["-DLIBCXXABI_ENABLE_EXCEPTIONS=OFF"])
        .args(["-DLIBCXXABI_ENABLE_NEW_DELETE_DEFINITIONS=ON"])
        .args(["-DLIBCXXABI_AVAILABILITY_MINIMUM_HEADER_VERSION=2"])
        .args(["-DLIBCXXABI_INCLUDE_TESTS=OFF", "-DLIBCXXABI_USE_LLVM_UNWINDER=OFF"])
        .args(["-DLIBCXXABI_ENABLE_STATIC_UNWINDER=OFF"])
        .args(["-DLIBCXXABI_SHARED_OUTPUT_NAME=cxxabi-shared"]);
    step(&mut configure_abi, "configuring libc++abi")?;

    let mut build_abi = Command::new(&ninja);
    build_abi.args(["-C"]).arg(&libcxxabi_build);
    step(&mut build_abi, "building libc++abi")?;

    // Merge the two archives into the one object file Mesa links.
    let merge = base.join("merge-tmp");
    let runtime = base.join("minix-runtime");
    remove_dir_all(&merge)?;
    remove_dir_all(&runtime)?;
    fs::create_dir_all(&merge)?;
    for archive in [
        libcxxabi_build.join("lib").join("libc++abi.a"),
        libcxx_build.join("lib").join("libc++.a"),
    ] {
        let mut extract = Command::new(&llvm_ar);
        extract.arg("x").arg(&archive).current_dir(&merge);
        step(&mut extract, "extracting an archive")?;
    }
    fs::create_dir_all(&runtime)?;
    let mut objects: Vec<PathBuf> = fs::read_dir(&merge)?
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .filter(|path| path.extension().is_some_and(|extension| extension == "obj"))
        .collect();
    objects.sort();
    let mut pack = Command::new(&llvm_ar);
    pack.arg("rcs")
        .arg(runtime.join("libstdc++.a"))
        .args(&objects)
        .current_dir(&merge);
    step(&mut pack, "merging the archives")
}

fn resolve(target: Option<&str>) -> io::Result<&'static Arch> {
    match target {
        Some(token) => arch::resolve(token),
        None => Ok(arch::DEFAULT),
    }
}

fn need(name: &str) -> io::Result<PathBuf> {
    toolchain::find_on_path(name).ok_or_else(|| {
        io::Error::new(
            io::ErrorKind::NotFound,
            format!("`{name}` not found on PATH (needed by the libc++ build)"),
        )
    })
}

fn remove_dir_all(directory: &Path) -> io::Result<()> {
    match fs::remove_dir_all(directory) {
        Ok(()) => Ok(()),
        Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(error),
    }
}

fn step(command: &mut Command, what: &str) -> io::Result<()> {
    if cc::run(command)? {
        Ok(())
    } else {
        Err(io::Error::other(format!("{what} failed")))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_toolchain_names_the_machine_and_the_triple() {
        let text = toolchain_text(Path::new("C:\\repo"), &arch::RISCV64);
        assert!(text.contains("set(CMAKE_SYSTEM_PROCESSOR riscv64)"));
        assert!(text.contains("set(MINIX_TRIPLE riscv64-unknown-none)"));
        assert!(text.contains("set(MINIX_ROOT \"C:/repo\")"));
    }

    #[test]
    fn the_toolchain_is_freestanding_and_pic() {
        let text = toolchain_text(Path::new("repo"), &arch::X86_64);
        assert!(text.contains("-ffreestanding"));
        assert!(text.contains("-fPIC"));
        assert!(text.contains("-mno-red-zone"));
        assert!(!text.contains("-fno-pic"));
    }

    #[test]
    fn riscv64_pins_its_psabi_in_the_c_flags() {
        let text = toolchain_text(Path::new("repo"), &arch::RISCV64);
        let flags = toolchain_c_flags(&arch::RISCV64);
        assert!(flags.contains("-march=rv64gc"));
        assert!(flags.contains("-mabi=lp64d"));
        assert!(!flags.contains("-mno-red-zone"));
        assert!(text.contains("-march=rv64gc"));
    }

    /// The C++ compile must not fall back to the host's C++ headers, and it has to
    /// see both the libc++ tree and the port's C headers.
    #[test]
    fn the_cxx_flags_are_hermetic_and_name_both_include_trees() {
        let cxx = toolchain_cxx_flags(&arch::X86_64);
        assert!(cxx.contains("-nostdinc++"));
        assert!(cxx.contains("libcxx/include"));
        assert!(cxx.contains("libcxxabi/include"));
        assert!(cxx.contains("tools/c-include"));
    }
}
